const CARDS = [
  ['愚者','✦','新的开始 · 自由 · 信任','犹豫 · 鲁莽 · 漫无方向','一个新阶段正在向你敞开。即使还看不清全貌，也可以带着好奇心迈出小小的一步。','你或许正在起点徘徊。先辨认风险与真正的渴望，再决定下一步。','如果暂时放下对结果的担忧，你最想尝试什么？'],
  ['魔术师','✧','创造 · 行动 · 潜能','分散 · 迟疑 · 失去信心','你已经拥有一些可用的资源。把想法落到一件具体的小事上，力量便会慢慢显现。','也许你把能力分散在太多方向。先选择一件重要的事，重新找回掌控感。','你手中已有哪项资源，可以从今天开始使用？'],
  ['女祭司','☾','直觉 · 宁静 · 内在智慧','忽略直觉 · 隐瞒 · 迷惘','答案未必需要立刻说出口。给自己一点安静，留意反复浮现的感受与线索。','外界的声音可能盖过了你的心声。暂缓判断，看看自己真正知道些什么。','当周围安静下来，你内心最清晰的声音是什么？'],
  ['皇后','❀','滋养 · 丰盛 · 关怀','消耗 · 依赖 · 忽略自己','让关怀从自己开始。你正在培育的关系或计划，需要耐心与持续的照料。','付出过多可能让你感到疲惫。试着把一部分温柔和时间留给自己。','哪一件小事能让你感到被好好照顾？'],
  ['皇帝','♜','结构 · 稳定 · 边界','僵化 · 控制 · 压力','清晰的边界与安排，能让眼前的事更加稳固。选择你愿意承担的责任。','过紧的控制也可能限制新的可能。看看哪些规则可以稍微松动。','你需要建立什么边界，才能更安心地前进？'],
  ['教皇','✶','学习 · 传统 · 指引','质疑 · 束缚 · 自主','借鉴可靠的经验与指引，会帮助你看见更完整的道路。','一套熟悉的方法可能已不完全适合你。允许自己重新理解它的意义。','你想保留哪些经验，又想改变哪种旧做法？'],
  ['恋人','♡','联结 · 选择 · 价值','摇摆 · 失衡 · 不一致','重要的选择值得与你珍视的价值观相互对照。坦诚沟通会让联结更深。','若内心与行动不一致，不妨先停下来确认真正的需求。','这个选择怎样才能更贴近你重视的事？'],
  ['战车','✧','方向 · 决心 · 前进','失控 · 急躁 · 阻力','聚焦一个方向，带着决心稳步前进。你不必同时解决所有问题。','过快的速度可能让你忽略内在的拉扯。调整节奏，重新握稳方向。','你现在最值得投入的一步是什么？'],
  ['力量','♌','勇气 · 温柔 · 韧性','自我怀疑 · 压抑 · 疲惫','真正的力量也可以很温柔。耐心地面对挑战，比与自己较劲更有帮助。','如果你已经很累，承认脆弱并寻求支持也是勇气。','你能用什么更温柔的方式对待自己？'],
  ['隐者','✺','独处 · 探索 · 洞察','孤立 · 逃避 · 迷失','放慢脚步，把注意力带回自己。独处能帮助你听清下一步的方向。','独处与隔绝之间有一道细线。需要时，让值得信任的人靠近。','此刻你需要怎样的安静或陪伴？'],
  ['命运之轮','✥','变化 · 周期 · 转机','停滞 · 抵抗 · 重复','变化正在发生。你无法控制所有转折，却可以选择如何回应它们。','重复的模式也许值得观察。找到其中能由你改变的一小部分。','面对变化，你可以主动调整什么？'],
  ['正义','⚖','平衡 · 诚实 · 判断','偏见 · 逃避 · 失衡','尽量看清事实，也诚实面对自己的感受。公平的决定需要完整的信息。','如果事情显得不公，先理清责任与界限，再采取行动。','还有哪一面事实值得你认真倾听？'],
  ['倒吊人','◇','暂停 · 换位 · 放下','拖延 · 抗拒 · 消耗','暂时停下来，不代表没有前进。换个角度，也许能看到新的出路。','若暂停变成了停滞，问问自己正在等待什么，以及是否可以先做一点点。','换一个视角，这件事会呈现什么不同？'],
  ['死神','✦','结束 · 转化 · 新生','抗拒 · 留恋 · 停滞','某个阶段正在结束。为它留出告别的空间，新的可能才能逐渐生长。','舍不得放下是自然的。先辨认你想保留的意义，再慢慢松开形式。','什么已经完成了它在你生命中的使命？'],
  ['节制','♧','调和 · 耐心 · 节奏','失衡 · 过度 · 急切','把不同需求放在一起慢慢调和。稳定的小步，比用力过猛更适合现在。','你或许正被两种极端拉扯。试着寻找可持续的中间地带。','怎样的节奏能让你走得更长远？'],
  ['恶魔','⛓','觉察 · 欲望 · 束缚','松绑 · 对抗 · 依赖','看见让你难以放手的习惯或关系，是恢复选择权的第一步。','你可能已意识到束缚所在。改变可以从一个清晰的边界开始。','是什么让你觉得自己别无选择？'],
  ['高塔','⚡','震动 · 真相 · 重建','抗拒变化 · 余波 · 修复','意外的变化可能打破旧有结构。先照顾好眼前的自己，再考虑如何重建。','变化后的余波需要时间消化。无需催促自己马上恢复如常。','在变化之中，什么仍是你可以依靠的？'],
  ['星星','✧','希望 · 修复 · 信任','失望 · 怀疑 · 疏离','一线希望正在出现。给自己留一点恢复的时间，也留一点对未来的信任。','希望变得微弱时，不必强迫自己乐观。寻找一个真实而微小的亮点。','现在有什么值得你重新相信？'],
  ['月亮','☽','感受 · 梦境 · 未知','困惑 · 焦虑 · 逐渐看清','眼前仍有不确定性。先接纳自己的感受，等更多信息浮现再做判断。','模糊之处可能正逐渐清晰。把猜测与事实分开，会让你更安心。','哪些是事实，哪些只是此刻的担忧？'],
  ['太阳','☼','清晰 · 喜悦 · 活力','疲惫 · 阴影 · 延迟','把目光放在已经生长的部分。坦率表达与简单的快乐，能带来更多能量。','如果光亮暂时被遮住，允许自己休息；喜悦不需要被勉强制造。','最近哪一刻让你感到真切的明亮？'],
  ['审判','✺','觉醒 · 回顾 · 呼唤','自责 · 迟疑 · 旧事','回望走过的路，你或许已经准备好回应一个更真实的方向。','过去的评价不必决定现在的你。用新的眼光看待自己的成长。','你正在听见怎样的内在呼唤？'],
  ['世界','◎','完成 · 整合 · 开阔','未竟 · 缺口 · 过渡','一个阶段的成果值得被看见。带着已有的经验，走向更开阔的下一程。','也许还有一处尚未收尾。给它一个恰当的结束，再开启新的篇章。','你想怎样庆祝或整理这一阶段的收获？']
].map((row, index) => ({id:index, roman:['0','I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX','XXI'][index],name:row[0],symbol:row[1],upright:row[2],reversed:row[3],uprightText:row[4],reversedText:row[5],reflection:row[6]}));

const app = document.getElementById('app');
const saved = readSaved();
const state = {screen:'home', topic:'自我探索', spread:1, question:'', deck:[], picked:[], result:saved};
const topics = [{name:'感情',hint:'关系与内心联结'},{name:'事业',hint:'方向与成长选择'},{name:'自我探索',hint:'与自己温柔相遇'}];
const positions = ['过去','现在','未来'];
const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function readSaved(){try{const data=JSON.parse(localStorage.getItem('mozi-tarot-result'));if(!data||!Array.isArray(data.cards)||![1,3].includes(data.spread))return null;const valid=data.cards.length===data.spread&&data.cards.every(c=>Number.isInteger(c.id)&&c.id>=0&&c.id<CARDS.length&&typeof c.reversed==='boolean');return valid?data:null}catch{return null}}
function persist(){try{localStorage.setItem('mozi-tarot-result',JSON.stringify(state.result))}catch{}}
function randomInt(max){if(window.crypto?.getRandomValues){const arr=new Uint32Array(1);crypto.getRandomValues(arr);return arr[0]%max}return Math.floor(Math.random()*max)}
function shuffle(items){const result=[...items];for(let i=result.length-1;i>0;i--){const j=randomInt(i+1);[result[i],result[j]]=[result[j],result[i]]}return result}
function setScreen(screen){state.screen=screen;render();window.scrollTo({top:0,behavior:'smooth'});app.focus({preventScroll:true})}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function progress(active){return `<div class="progress" aria-label="第 ${active} 步，共 3 步"><span class="${active===1?'active':''}">01 提问</span><span class="progress-line"></span><span class="${active===2?'active':''}">02 抽牌</span><span class="progress-line"></span><span class="${active===3?'active':''}">03 解读</span></div>`}
function renderHome(){app.innerHTML=`<section class="hero"><div class="hero-copy"><div class="hero-kicker">A MOMENT FOR YOURSELF</div><h1>在牌面之间，<br><em>遇见自己的答案。</em></h1><p class="hero-desc">放慢一点，想一想心里的问题。让一张牌成为一面镜子，照见此刻值得留意的方向。</p><div class="hero-actions"><button class="primary-btn" data-action="start">开启占卜 <span aria-hidden="true">→</span></button><button class="text-btn" data-action="guide">了解占卜方式 ↗</button></div>${state.result?'<button class="text-btn" data-action="resume" style="margin-top:23px">查看上次的解读 →</button>':''}<div class="hero-footnote"><span class="rule"></span>用一点时间，和自己好好相处</div></div><div class="hero-art" aria-hidden="true"><div class="orbit"><div class="orbit-arc"></div></div><span class="art-spark spark-a">✧</span><span class="art-spark spark-b">✶</span><span class="art-spark spark-c">✦</span><div class="art-card left"></div><div class="art-card right"></div><div class="art-card main"><span class="top-symbol">✧</span><div class="moon-illustration"><span class="moon-glyph">☾</span><span class="moon-star a">✦</span><span class="moon-star b">✧</span></div><span class="bottom-symbol">MOZI TAROT</span></div><span class="art-caption">I · LISTEN WITHIN</span></div></section><section class="intro-strip" aria-label="占卜步骤"><div class="intro-label">一场与自己的对话</div><div class="intro-steps"><span><strong>01</strong> 静心提问</span><span><strong>02</strong> 凭直觉选牌</span><span><strong>03</strong> 阅读与思考</span></div></section>`}
function renderForm(){app.innerHTML=`<section class="flow"><div class="flow-top"><button class="back-link" data-action="home">← 返回首页</button>${progress(1)}</div><div class="flow-heading"><div class="eyebrow">THE QUESTION</div><h2>此刻，你想探索什么？</h2><p>没有标准答案，只需从你真正关心的地方开始。</p></div><div class="ritual-panel"><div class="field-label">01 / 选择一个主题</div><div class="choice-grid">${topics.map(t=>`<button class="choice ${state.topic===t.name?'selected':''}" data-topic="${t.name}" aria-pressed="${state.topic===t.name}"><span class="choice-title">${t.name}</span><span class="choice-hint">${t.hint}</span></button>`).join('')}</div><label class="field-label" for="question">02 / 写下你的问题 <span style="font-weight:300;color:#988ca7">（选填）</span></label><textarea id="question" class="question-box" maxlength="160" placeholder="例如：我该如何面对眼前的变化？">${escapeHtml(state.question)}</textarea><p class="field-note">试着提出开放式问题，例如“我可以如何……”</p><div class="field-label spread-heading">03 / 选择牌阵</div><div class="spread-grid"><button class="choice spread-choice ${state.spread===1?'selected':''}" data-spread="1" aria-pressed="${state.spread===1}"><span class="spread-icon">✧</span><span><span class="choice-title">单张启示</span><span class="choice-hint">聚焦当下的一份提醒</span></span></button><button class="choice spread-choice ${state.spread===3?'selected':''}" data-spread="3" aria-pressed="${state.spread===3}"><span class="spread-icon">✧ ✧ ✧</span><span><span class="choice-title">时光三牌</span><span class="choice-hint">过去、现在与未来</span></span></button></div></div><div class="flow-action"><button class="primary-btn" data-action="draw">继续，去抽牌 <span aria-hidden="true">→</span></button></div></section>`}
function newDeck(){state.deck=shuffle(CARDS.map(c=>c.id)).slice(0,12);state.picked=[];setScreen('draw')}
function renderDraw(){const count=state.picked.length;app.innerHTML=`<section class="flow"><div class="flow-top"><button class="back-link" data-action="form">← 返回提问</button>${progress(2)}</div><div class="flow-heading draw-header"><div class="eyebrow">THE DRAW</div><h2>深呼吸，凭直觉选牌</h2><p>让目光停在吸引你的牌背，轻点它。</p></div><div class="draw-status" aria-live="polite">已选择 ${count} / ${state.spread} 张</div><div class="deck-stage"><div class="deck" role="group" aria-label="选择塔罗牌">${state.deck.map((id,index)=>{const selected=state.picked.some(p=>p.index===index);const offset=Math.abs(index-5.5)*4;const rotation=(index-5.5)*3.2;return `<button class="draw-card ${selected?'selected':''}" style="--offset:${offset}px;--rotation:${rotation}deg" data-card-index="${index}" aria-label="${selected?'已选中的':'选择第'}${index+1}张牌" ${selected||count>=state.spread?'disabled':''}><span class="draw-card-inner"><span class="draw-card-glyph">☾</span></span></button>`}).join('')}</div></div><p class="draw-hint">每一次选择，都是与此刻的自己相遇。</p><div class="draw-action">${count===state.spread?'<button class="primary-btn" data-action="reveal">翻开我的牌 <span aria-hidden="true">→</span></button>':''}</div></section>`}
function cardText(card,position){const base=card.reversed?card.data.reversedText:card.data.uprightText;if(state.result.spread===1)return base;const prefix=position==='过去'?'回望过去，这张牌提醒你：':position==='现在'?'来到当下，这张牌邀请你：':'面向未来，这张牌提示一种可能：';return prefix+base}
function renderResult(){const result=state.result;if(!result){setScreen('home');return}const cards=result.cards.map(c=>({data:CARDS[c.id],reversed:c.reversed}));app.innerHTML=`<section class="result-page"><div class="flow-top"><button class="back-link" data-action="home">← 返回首页</button>${progress(3)}</div><div class="flow-heading"><div class="eyebrow">YOUR READING</div><h2>这是属于你的牌面</h2><p>不妨慢慢读，让真正触动你的那句话留下来。</p></div><div class="result-question"><strong>${escapeHtml(result.topic)}</strong>${result.question?` · “${escapeHtml(result.question)}”`:' · 此刻的探索'}</div><div class="result-grid ${result.spread===1?'single-result':''}" style="--result-columns:${result.spread}">${cards.map((card,index)=>`<article class="result-card"><div class="result-position">${result.spread===1?'此刻的启示':`${String(index+1).padStart(2,'0')} · ${positions[index]}`}</div><div class="reading-visual ${card.reversed?'reverse':''}" aria-hidden="true"><span class="reading-symbol">${card.data.symbol}</span><span class="reading-roman">${card.data.roman}</span></div><h3 class="reading-name">${card.data.name}</h3><div class="reading-orientation">${card.reversed?'逆位':'正位'}</div><p class="reading-keywords">${card.reversed?card.data.reversed:card.data.upright}</p><div class="reading-divider"></div><p class="reading-text">${cardText(card,positions[index])}</p></article>`).join('')}</div><div class="reflection"><span>留给自己的一个问题</span>${escapeHtml(cards[result.spread===1?0:1].data.reflection)}</div><div class="result-actions"><button class="outline-btn" data-action="copy">复制解读</button><button class="outline-btn" data-action="download">保存结果图片</button><button class="primary-btn" data-action="restart">重新抽牌 <span aria-hidden="true">↗</span></button></div></section>`}
function renderGuide(){app.innerHTML=`<section class="guide"><div class="flow-heading"><div class="eyebrow">A GENTLE GUIDE</div><h2>让一张牌，开启一次对话。</h2><p>塔罗不替你决定未来。它提供一个角度，帮助你听见自己的想法。</p></div><div class="guide-grid"><article class="guide-item"><span class="guide-num">01</span><h3>静心提问</h3><p>选择你在意的主题。与其问“结果会是什么”，不如问“我能如何理解或面对这件事”。</p></article><article class="guide-item"><span class="guide-num">02</span><h3>凭直觉选牌</h3><p>选择单张牌，或过去、现在、未来三张牌。无需分析哪张“更好”，只要跟随第一眼的感觉。</p></article><article class="guide-item"><span class="guide-num">03</span><h3>留下触动</h3><p>阅读牌义时，留意与你经历产生联系的部分。把它当作提问的起点，而非必须遵从的结论。</p></article></div><div class="guide-cta"><button class="primary-btn" data-action="start">开始我的占卜 <span aria-hidden="true">→</span></button></div></section>`}
function render(){if(state.screen==='home')renderHome();else if(state.screen==='form')renderForm();else if(state.screen==='draw')renderDraw();else if(state.screen==='result')renderResult();else renderGuide()}
function reveal(){if(state.picked.length!==state.spread)return;state.result={topic:state.topic,spread:state.spread,question:state.question.trim(),cards:state.picked.map(p=>({id:state.deck[p.index],reversed:p.reversed}))};persist();setScreen('result')}
function resultText(){const r=state.result;const lines=['墨紫塔罗 · 我的牌面',`主题：${r.topic}`,r.question?`问题：${r.question}`:''];r.cards.forEach((c,i)=>{const data=CARDS[c.id];lines.push(`${r.spread===1?'此刻的启示':positions[i]}｜${data.name} · ${c.reversed?'逆位':'正位'}`,`${c.reversed?data.reversed:data.upright}`,`${c.reversed?data.reversedText:data.uprightText}`)});lines.push(`留给自己的问题：${CARDS[r.cards[r.spread===1?0:1].id].reflection}`);return lines.filter(Boolean).join('\n')}
async function copyResult(){const value=resultText();try{await navigator.clipboard.writeText(value);toast('解读已复制')}catch{const box=document.createElement('textarea');box.value=value;document.body.append(box);box.select();try{document.execCommand('copy');toast('解读已复制')}catch{toast('复制失败，请手动选择文字')}box.remove()}}
function xml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]))}
function wrapText(text,max){const chars=[...text];const lines=[];while(chars.length)lines.push(chars.splice(0,max).join(''));return lines}
function downloadResult(){const r=state.result;const width=960;const cardBlock=165;const height=330+r.cards.length*cardBlock+150;let y=235;const parts=[`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#2d2040"/><stop offset="1" stop-color="#171124"/></linearGradient></defs><rect width="100%" height="100%" fill="url(#bg)"/><rect x="28" y="28" width="904" height="${height-56}" rx="12" fill="none" stroke="#d9b978" opacity=".65"/><rect x="39" y="39" width="882" height="${height-78}" rx="8" fill="none" stroke="#d9b978" opacity=".22"/><text x="480" y="92" text-anchor="middle" fill="#d9b978" font-size="17" letter-spacing="6" font-family="serif">✧ MOZI TAROT ✧</text><text x="480" y="145" text-anchor="middle" fill="#f4eee8" font-size="35" font-family="serif">墨紫塔罗 · 我的牌面</text><text x="480" y="190" text-anchor="middle" fill="#b8abc7" font-size="18" font-family="sans-serif">${xml(r.topic)}${r.question?' · '+xml([...r.question].slice(0,25).join('')):''}</text>`];r.cards.forEach((c,i)=>{const data=CARDS[c.id],label=r.spread===1?'此刻的启示':positions[i];parts.push(`<line x1="110" y1="${y-20}" x2="850" y2="${y-20}" stroke="#d9b978" opacity=".25"/><text x="120" y="${y+24}" fill="#d9b978" font-size="31" font-family="serif">${xml(data.symbol)}  ${xml(label)} · ${xml(data.name)} ${c.reversed?'逆位':'正位'}</text><text x="120" y="${y+57}" fill="#cbb9d2" font-size="17" font-family="sans-serif">${xml(c.reversed?data.reversed:data.upright)}</text>`);wrapText(c.reversed?data.reversedText:data.uprightText,35).slice(0,3).forEach((line,j)=>parts.push(`<text x="120" y="${y+91+j*28}" fill="#eee6f2" font-size="20" font-family="sans-serif">${xml(line)}</text>`));y+=cardBlock});const reflection=CARDS[r.cards[r.spread===1?0:1].id].reflection;parts.push(`<text x="120" y="${y+26}" fill="#d9b978" font-size="17" font-family="sans-serif">留给自己的一个问题</text><text x="120" y="${y+66}" fill="#f4eee8" font-size="21" font-family="serif">${xml(reflection)}</text><text x="480" y="${height-72}" text-anchor="middle" fill="#9386a4" font-size="14" font-family="sans-serif">塔罗解读用于自我探索与娱乐</text></svg>`);const blob=new Blob([parts.join('')],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='墨紫塔罗-我的牌面.svg';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('结果图片已保存')}
document.addEventListener('click',event=>{const topic=event.target.closest('[data-topic]');if(topic){state.topic=topic.dataset.topic;renderForm();return}const spread=event.target.closest('[data-spread]');if(spread){state.spread=Number(spread.dataset.spread);renderForm();return}const card=event.target.closest('[data-card-index]');if(card&&state.screen==='draw'){const index=Number(card.dataset.cardIndex);if(state.picked.length<state.spread&&!state.picked.some(p=>p.index===index)){state.picked.push({index,reversed:randomInt(2)===0});renderDraw()}return}const target=event.target.closest('[data-action]');if(!target)return;switch(target.dataset.action){case'home':setScreen('home');break;case'guide':setScreen('guide');break;case'start':setScreen('form');break;case'form':setScreen('form');break;case'draw':newDeck();break;case'reveal':reveal();break;case'resume':if(state.result)setScreen('result');break;case'restart':state.question='';state.topic='自我探索';state.spread=1;setScreen('form');break;case'copy':copyResult();break;case'download':downloadResult();break}});
document.addEventListener('input',event=>{if(event.target.id==='question')state.question=event.target.value});
render();
